/**
 * Map backend entities to images. Listings with uploaded photos
 * (`POST /me/listings/{id}/photos` → `/media/uploads/…`) show those; the rest get a
 * deterministic, category-appropriate set from the seeded imagery in public/seed/
 * (generated by `npm run seed`).
 */
import { API_BASE } from "./api";

const PER_CATEGORY = 4;
const KNOWN = ["house", "villa", "apartment", "tower", "office", "shop", "plot", "farmhouse", "building", "floor", "space", "mall"];

function hash(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
}

type Imageable = { id?: string; title?: string; category?: string | null; image_urls?: string[]; kanal_area?: number | null; price?: number };

function categoryFor(p: Imageable): string {
  const c = (p.category ?? "").toLowerCase();
  const t = (p.title ?? "").toLowerCase();
  if (t.includes("farmhouse")) return "farmhouse";
  if (c === "house" && ((p.kanal_area ?? 0) >= 1 || (p.price ?? 0) >= 80_000_000)) return "villa";
  if (KNOWN.includes(c)) return c;
  if (/(tower|mall|plaza)/.test(t)) return "tower";
  return "house";
}

/** Photos may be absolute URLs, backend uploads (/media/…) or seed paths (/seed/…). */
export function resolveImage(url: string): string {
  if (url.startsWith("/media/")) return `${API_BASE}${url}`;
  return url;
}

/** Primary cover image for a property. Real uploaded images win over seeds. */
export function coverImage(p: Imageable): string {
  if (p.image_urls?.length) return resolveImage(p.image_urls[0]!);
  const cat = categoryFor(p);
  const n = (hash(p.id ?? p.title ?? cat) % PER_CATEGORY) + 1;
  return `/seed/properties/${cat}-${n}.svg`;
}

/** Gallery: exterior variants + interiors + a floor plan. */
export function gallery(p: Imageable): string[] {
  if (p.image_urls?.length) return p.image_urls.map(resolveImage);
  const cat = categoryFor(p);
  const h = hash(p.id ?? p.title ?? cat);
  const ext = Array.from({ length: PER_CATEGORY }, (_, i) => `/seed/properties/${cat}-${((h + i) % PER_CATEGORY) + 1}.svg`);
  const isLand = cat === "plot";
  const interiors = isLand ? [] : [0, 1, 2].map((i) => `/seed/interiors/interior-${((h + i) % 6) + 1}.svg`);
  const plan = isLand ? [] : [`/seed/plans/plan-${(h % 3) + 1}.svg`];
  return [...ext.slice(0, 3), ...interiors, ...plan];
}

/** A Wikimedia Commons thumbnail at a smaller standard width (cards don't need 1280 px). */
export function sized(url: string, width: 330 | 500 | 960 | 1280 = 960): string {
  return url.includes("upload.wikimedia.org") ? url.replace(/\/\d+px-/, `/${width}px-`) : url;
}

/** A city's photo: its real (credited) image when it has one, else the bundled illustration. */
export function cityImage(name?: string | null, image?: string | null): string {
  if (image) return sized(image, 960);
  const n = (name ?? "").toLowerCase();
  if (["lahore", "karachi", "islamabad", "rawalpindi"].includes(n)) return `/seed/cities/${n}.svg`;
  return `/seed/cities/rawalpindi.svg`;
}

/** Image for a society / big project / story, chosen by keyword then hash. */
export function themedImage(key: string, hint?: string | null): string {
  const h = (hint ?? "").toLowerCase();
  let cat = "building";
  if (/(mall|plaza|arcade|retail|shop)/.test(h)) cat = "mall";
  else if (/(tower|office|corporate|tech)/.test(h)) cat = "tower";
  else if (/(compound|villa|garden|housing|residence|home|house)/.test(h)) cat = "villa";
  else if (/(apartment|flat|heights)/.test(h)) cat = "apartment";
  else if (/(plot|land|farm)/.test(h)) cat = "plot";
  return `/seed/properties/${cat}-${(hash(key) % PER_CATEGORY) + 1}.svg`;
}

export const HERO = {
  panorama: "/seed/hero/islamabad-panorama.webp",
  villa: "/seed/hero/luxury-villa.webp",
  aiMap: "/seed/hero/ai-map.webp",
  landscape: "/seed/hero/pakistan-landscape.webp",
  headerEn: "/brand/header-en.webp",
  headerUr: "/brand/header-ur.webp",
};

export const BRAND = {
  logo: "/brand/logo-en.webp",
  logoUr: "/brand/logo-ur.webp",
  mark: "/brand/logo-mark.webp",
};

/**
 * Downscale a picked photo to a JPEG data URL (max 1600px, ~82% quality) for
 * `POST /me/listings/{id}/photos`, which accepts JPEG / PNG / WebP up to 5 MB.
 */
export async function compressImage(file: File, max = 1600, quality = 0.82): Promise<string> {
  const url = URL.createObjectURL(file);
  try {
    const img = await new Promise<HTMLImageElement>((ok, fail) => {
      const i = new Image();
      i.onload = () => ok(i);
      i.onerror = () => fail(new Error(`${file.name} isn’t a supported image`));
      i.src = url;
    });
    const scale = Math.min(1, max / Math.max(img.width, img.height));
    const canvas = document.createElement("canvas");
    canvas.width = Math.round(img.width * scale);
    canvas.height = Math.round(img.height * scale);
    canvas.getContext("2d")!.drawImage(img, 0, 0, canvas.width, canvas.height);
    return canvas.toDataURL("image/jpeg", quality);
  } finally {
    URL.revokeObjectURL(url);
  }
}
